import java.util.*;
import java.io.*;

public class Main {
    static final int p1 = 998244353;
    static final int p2 = 1000000007;
    static final int B = 1000000;
    static List<Integer>[] v = new ArrayList[7];
    static int[] sum = new int[7];
    static long n, ord, ans;

    static {
        for (int i = 0; i < 7; i++) {
            v[i] = new ArrayList<>();
        }
    }

    static void dfs1(long x, int len) {
        ord++;
        v[len].add((int)((ord - x + p1) % p1));
        sum[len] = (sum[len] + v[len].get(v[len].size() - 1)) % p2;
        if (len == 6) return;
        for (int i = 0; i <= 9; i++) {
            dfs1(x * 10 + i, len + 1);
        }
    }

    static void dfs2(long x) {
        if (x > n) return;
        if (x * B + B - 1 <= n && x * B * 10 > n) {
            long now = ord;
            for (int i = 0, m = 1; i <= 6; i++, m *= 10) {
                int sz = v[i].size();
                int dt = (int)(((now - x * m) % p1 + p1) % p1);
                int pos = lowerBound(v[i], p1 - dt);
                ans = (ans + (long) dt * sz + sum[i]) % p2;
                ans = (ans - (long) (sz - pos) * p1 % p2 + p2) % p2;
                ord += sz;
            }
            return;
        }
        ord++;
        ans = (ans + ((ord - x) % p1 + p1) % p1) % p2;
        for (int i = 0; i <= 9; i++) {
            dfs2(x * 10 + i);
        }
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine());
        dfs1(0, 0);
        ord = 0;
        for (int i = 0; i <= 6; i++) {
            Collections.sort(v[i]);
        }
        for (int i = 1; i <= 9; i++) {
            dfs2(i);
        }
        System.out.println(ans);
    }
}
